			using (StringFormat sf = new StringFormat(StringFormat.GenericTypographic)			{				Alignment = alignH,  // Near(left), Center(middle), Far(right)				LineAlignment = alignV,  // Near(top), Center(middle), Far(bottom)			}) {				using (SolidBrush brush = new SolidBrush(textColor)) {					// If require rotation					if (angle != 0) {						// Save the graphics state.						var state = g.Save();						g.ResetTransform();						// Set rotation point						var rectCenter = new Point(							layoutRect.Left + layoutRect.Width / 2, 							layoutRect.Top + layoutRect.Height / 2						);						g.TranslateTransform(rectCenter.X, rectCenter.Y);						// Rotate the Graphics object.						g.RotateTransform(angle);						SizeF textSize = g.MeasureString(text, font);						// Get start point						PointF drawPoint = new PointF(-textSize.Width / 2f, -textSize.Height / 2f);						//Draw text						g.DrawString(text, font, brush, drawPoint);						// Restore transform						g.Restore(state);					} else {						g.DrawString(text, font, brush, layoutRect, sf);					}				}			}//OR            // Is hidden or No Text > Skip            if (IsHidden || Text.Length == 0) return;            g.SmoothingMode = SmoothingMode.AntiAlias;            var rect = ClientRectangle.Clone();            if (offsetLocation) rect.Offset(Location);            // If rotation required, temporaly rotate graphics             var requireRotation = Rotation != 0;            if (requireRotation) {                // Set rotation point                g.TranslateTransform(rect.Left + rect.Width / 2, rect.Top + rect.Height / 2);                // Rotate the Graphics object.                g.RotateTransform(Rotation);                SizeF textSize = g.MeasureString(Text, Font);                rect = new Rectangle(                     (int)(textSize.Width / -2),                     (int)(textSize.Height / -2),                     ClientRectangle.Width,                     ClientRectangle.Height                );            }            // DRAW >            DrawingUtils.DrawText(                g, Text, Font, ForeColor, rect, new Point(), new Point(), 0,                Translate.GetStringAlignmentHorizontal(TextAlignmentHorizontal),                Translate.GetStringAlignmentVertical(TextAlignmentVertical)            );            // DRAW <            // If graphics was rotated, reset transformations.            if (requireRotation) g.ResetTransform();